/* @lc app=leetcode id=3587 lang=kotlin */ class Solution { fun cost(p: List<Int>, off: Int): Long = p.indices.sumOf { Math.abs(p[it] - (2 * it + off)).toLong() } fun minSwaps(nums: IntArray): Int = nums.indices.filter { nums[it] % 2 == 0 }.let { ev -> nums.size.minus(ev.size).let { od -> if (ev.size == od) minOf(cost(ev, 0), cost(ev, 1)).toInt() else if (ev.size == od + 1) cost(ev, 0).toInt() else if (od == ev.size + 1) cost(ev, 1).toInt() else -1 } } }